statement:
One table records incoming transactions:

- `Transactions(id, country, state, amount, trans_date)`: one row per transaction; `id` is unique. `state` is either `'approved'` or `'declined'`. `country` may be `null`; the other columns never are.

Group the transactions by calendar month (`trans_date` written as `YYYY-MM`) and country; a `null` country forms its own group. For every group that has at least one transaction, report:

- `month`: the month as text, for example `2018-12`;
- `country`;
- `trans_count`: the number of transactions;
- `approved_count`: the number of approved transactions (`0` if none);
- `trans_total_amount`: the sum of all amounts;
- `approved_total_amount`: the sum of the approved amounts (`0` if none, never `null`).

Rows may come in any order.

validator:
function validate(input) {
  const [{ Transactions = [] }] = input;
  const ids = new Set();
  for (const [id, , state, amount, date] of Transactions) {
    if (id === null || state === null || amount === null || date === null) return 'Only country may be null in Transactions.';
    if (ids.has(id)) return `id ${id} appears twice in Transactions.`;
    ids.add(id);
    if (state !== 'approved' && state !== 'declined') return `state must be 'approved' or 'declined', not '${state}'.`;
  }
  return null;
}

generator:
function generate(rand, size) {
  const pick = (list) => list[Math.floor(rand() * list.length)];
  const day = (n) => new Date(Date.UTC(2018, 10, 20 + n)).toISOString().slice(0, 10);
  const small = size === 'small';
  const countries = small ? ['US', 'DE', 'FR', null] : ['US', 'DE', 'FR', 'IN', 'BR', 'JP', 'CN', 'MX', null];
  const amounts = [0, 500, 1000, 2000, 3000];
  const rows = small ? Math.floor(rand() * 9) : 2000;
  const Transactions = [];
  for (let i = 0; i < rows; i++) {
    // Small cases span about three months around a new year so groups collide and split.
    const date = day(Math.floor(rand() * (small ? 90 : 730)));
    const amount = small ? pick(amounts) : Math.floor(rand() * 5000);
    Transactions.push([100 + i, pick(countries), rand() < 0.6 ? 'approved' : 'declined', amount, date]);
  }
  return [{ Transactions }];
}
